// The bundled food table (TECH-SPEC section 9). `foods.json` is generated by `pnpm foods:build` from USDA SR Legacy and
// FNDDS, SG FoodID and `data/food-list.csv`; nobody types a nutrient value. It loads lazily and works offline.
import type { MealItem } from '../../../shared/records';

export type FoodTag = 'dense' | 'protein' | 'drink' | 'oil' | 'staple' | 'thai';
export type Food = {
  id: string;
  name: string;
  aliases: string[];
  per100: { kcal: number; protein: number; carbs: number; fat: number; fiber?: number };
  /** the first is the default */
  portions: Array<{ label: string; grams: number }>;
  tags: FoodTag[];
  /** the table and the food's id in it: an FDC id for USDA, a crId for SG FoodID */
  source: { set: 'usda-sr-legacy' | 'usda-fndds' | 'sg-foodid'; id: string };
};

let table: Promise<Food[]> | null = null;
/** The table, loaded once. A failed load (offline before it was cached) retries on the next call. */
export function loadFoods(): Promise<Food[]> {
  table ??= import('./foods.json').then((m) => m.default as Food[]).catch((e) => { table = null; throw e; });
  return table;
}

/** Lower case, accents dropped, Thai script kept (U+0E00 to U+0E7F), anything else a space. */
export const norm = (s: string) => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9\u0e00-\u0e7f ]+/g, ' ').replace(/\s+/g, ' ').trim();

/** 3 prefix, 2 word start, 1 substring, 0 no match: of the query against one name or alias. */
function score(text: string, q: string) {
  const s = norm(text);
  if (s.startsWith(q)) return 3;
  if (s.includes(` ${q}`)) return 2;
  return s.includes(q) ? 1 : 0;
}

/** Scored match over name and aliases: prefix beats word start beats substring, shorter names win ties. No library. */
export function searchFoods(foods: Food[], query: string, limit = 30): Food[] {
  const q = norm(query);
  if (!q) return [];
  return foods
    .map((f) => ({ f, s: Math.max(score(f.name, q), ...f.aliases.map((a) => score(a, q))) }))
    .filter((x) => x.s > 0)
    .sort((a, b) => b.s - a.s || a.f.name.length - b.f.name.length || a.f.name.localeCompare(b.f.name))
    .slice(0, limit)
    .map((x) => x.f);
}

const r1 = (n: number) => Math.round(n * 10) / 10;
/** A meal item for this many grams of a food: whole kcal, macros to one decimal, labelled Database. */
export function itemFor(f: Food, grams: number): MealItem {
  const k = grams / 100;
  return { name: f.name, grams, kcal: Math.round(f.per100.kcal * k), protein: r1(f.per100.protein * k), carbs: r1(f.per100.carbs * k), fat: r1(f.per100.fat * k), source: 'db', foodId: f.id };
}
